<script setup lang="ts">
import type { AdmissionAction, AdmissionContentItem, AdmissionSection } from '@/mocks/convocatorias.mock';
defineProps<{ items: AdmissionContentItem[] }>();
const emit = defineEmits<{ editSection: [section: AdmissionSection]; editAction: [action: AdmissionAction, parentId?: string]; remove: [id: string, parentId?: string]; move: [index: number, delta: number, parentId?: string]; addAction: [parentId?: string] }>();
const isSection = (item: AdmissionContentItem): item is AdmissionSection => item.tipo === 'section';
const typeIcon = (type: AdmissionAction['tipo']) => ({ richText: 'mdi-text-box-outline', documentUpload: 'mdi-file-upload-outline', confirmation: 'mdi-check-decagram-outline' }[type]);
const typeLabel = (type: AdmissionAction['tipo']) => ({ richText: 'Texto enriquecido', documentUpload: 'Carga de documentos', confirmation: 'Confirmación' }[type]);
</script>
<template><div><template v-for="(item, index) in items" :key="item.id"><v-card v-if="isSection(item)" variant="outlined" class="mb-3 section-node"><v-card-text><div class="d-flex align-start justify-space-between ga-2"><div class="d-flex ga-3"><v-icon color="primary" class="mt-1">mdi-folder-outline</v-icon><div><div class="font-weight-medium">{{ item.nombre }}</div><div v-if="item.descripcion" class="text-caption text-medium-emphasis">{{ item.descripcion }}</div></div></div><div class="node-actions"><v-btn size="x-small" variant="text" icon="mdi-arrow-up" :disabled="index === 0" @click="emit('move', index, -1)" /><v-btn size="x-small" variant="text" icon="mdi-arrow-down" :disabled="index === items.length - 1" @click="emit('move', index, 1)" /><v-btn size="x-small" variant="text" icon="mdi-pencil" @click="emit('editSection', item)" /><v-btn size="x-small" variant="text" color="error" icon="mdi-delete-outline" @click="emit('remove', item.id)" /></div></div><div class="section-blocks mt-3"><v-card v-for="(block, blockIndex) in item.contenido.filter(child => child.tipo !== 'section')" :key="block.id" variant="outlined" class="mb-2"><v-card-text class="d-flex align-center justify-space-between py-2"><div class="d-flex ga-2 align-center"><v-icon size="20" color="primary">{{ typeIcon(block.tipo) }}</v-icon><div><div class="font-weight-medium">{{ block.nombre }}</div><div class="text-caption text-medium-emphasis">{{ typeLabel(block.tipo) }}</div></div></div><div><v-btn size="x-small" variant="text" icon="mdi-arrow-up" :disabled="blockIndex === 0" @click="emit('move', blockIndex, -1, item.id)" /><v-btn size="x-small" variant="text" icon="mdi-arrow-down" :disabled="blockIndex === item.contenido.filter(child => child.tipo !== 'section').length - 1" @click="emit('move', blockIndex, 1, item.id)" /><v-btn size="x-small" variant="text" icon="mdi-pencil" @click="emit('editAction', block, item.id)" /><v-btn size="x-small" variant="text" color="error" icon="mdi-delete-outline" @click="emit('remove', block.id, item.id)" /></div></v-card-text></v-card></div><v-btn size="small" variant="text" color="primary" prepend-icon="mdi-plus" @click="emit('addAction', item.id)">Agregar bloque</v-btn></v-card-text></v-card><v-card v-else variant="outlined" class="mb-2"><v-card-text class="d-flex align-center justify-space-between py-2"><div class="d-flex ga-2 align-center"><v-icon size="20" color="primary">{{ typeIcon(item.tipo) }}</v-icon><div><div class="font-weight-medium">{{ item.nombre }}</div><div class="text-caption text-medium-emphasis">{{ typeLabel(item.tipo) }}</div></div></div><div><v-btn size="x-small" variant="text" icon="mdi-arrow-up" :disabled="index === 0" @click="emit('move', index, -1)" /><v-btn size="x-small" variant="text" icon="mdi-arrow-down" :disabled="index === items.length - 1" @click="emit('move', index, 1)" /><v-btn size="x-small" variant="text" icon="mdi-pencil" @click="emit('editAction', item)" /><v-btn size="x-small" variant="text" color="error" icon="mdi-delete-outline" @click="emit('remove', item.id)" /></div></v-card-text></v-card></template></div></template>
<style scoped>.section-node { background: rgba(var(--v-theme-primary), .018); }.section-blocks { margin-left: 20px; padding-left: 12px; border-left: 2px solid rgb(var(--v-theme-borderColor)); }</style>
